import{_ as o,o as i,c as a,a2 as r}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"Scrivere, link e proprietà","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/scrivere-link-proprieta.md","filePath":"user-guide/scrivere-link-proprieta.md"}'),t={name:"user-guide/scrivere-link-proprieta.md"};function n(c,e,l,d,s,p){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="scrivere-link-e-proprieta" tabindex="-1">Scrivere, link e proprietà <a class="header-anchor" href="#scrivere-link-e-proprieta" aria-label="Permalink to &quot;Scrivere, link e proprietà&quot;">​</a></h1><h2 id="le-tre-modalita" tabindex="-1">Le tre modalità <a class="header-anchor" href="#le-tre-modalita" aria-label="Permalink to &quot;Le tre modalità&quot;">​</a></h2><p>Ogni nota si apre in una di tre modalità (<code>Mod+E</code> alterna lettura/modifica, <code>Mod+Maiusc+E</code> sorgente/anteprima, o dalla palette: <em>Modalità Live Preview / sorgente / lettura</em>):</p><ul><li><strong>Live:</strong> è la modalità predefinita (nei comandi e nella palette: <em>Modalità Live Preview</em>). È un editor WYSIWYG: scrivete e vedete subito il risultato, senza simboli Markdown. I <code>[[wikilink]]</code> e gli embed mostrano il sorgente quando il cursore è dentro. Il file resta Markdown e non viene riscritto: i blocchi che non toccate restano com&#39;erano. Accanto al blocco sotto il puntatore compare una maniglia: il «+» aggiunge un blocco e apre il menu <code>/</code>, la presa lo trascina (da tastiera: <code>/</code> e <code>Alt+↑/↓</code>). Selezionando del testo compare una barra con grassetto, corsivo, barrato, evidenziato, codice, formula e link. Alcuni costrutti (commenti <code>%%</code>, note a piè di pagina, HTML, link a riferimento, formule <code>$$</code> in linea) sono blocchi non modificabili in Live: si modificano in Sorgente. Numeri di riga, cursori multipli e selezione rettangolare ci sono solo in Sorgente. Una nota molto grande (oltre 250.000 caratteri, 3.000 blocchi o 150 blocchi di codice) si apre in Sorgente, con un avviso.</li><li><strong>Sorgente:</strong> Markdown puro, con colorazione. È l&#39;unica modalità in cui si vede il frontmatter YAML della nota.</li><li><strong>Lettura:</strong> vista di sola lettura, con embed e blocchi renderizzati.</li></ul><h2 id="formattazione" tabindex="-1">Formattazione <a class="header-anchor" href="#formattazione" aria-label="Permalink to &quot;Formattazione&quot;">​</a></h2><p>Supportati: titoli, elenchi, attività (<code>- [ ]</code>, con stati personalizzati), citazioni, tabelle, codice, note a piè di pagina, formule <code>$...$</code> e <code>$$...$$</code>, diagrammi Mermaid, callout (<code>&gt; [!note]</code>), evidenziato <code>==testo==</code>, commenti <code>%%testo%%</code>. Scorciatoie: grassetto <code>Mod+B</code>, corsivo <code>Mod+I</code>, evidenzia <code>Mod+Maiusc+H</code>, barrato <code>Mod+Maiusc+X</code>, codice <code>Mod+Maiusc+C</code>, link <code>Mod+K</code>, wikilink <code>Mod+Maiusc+K</code>, attività <code>Mod+Invio</code>. Digitando <code>/</code> si apre il menu dei comandi di inserimento (in Live a gruppi e con icone). In Live <code>:smile:</code> scrive direttamente il carattere (😄), mostrato con una grafica Twemoji locale; in Sorgente resta <code>:smile:</code>. Invio in un paragrafo ne crea uno nuovo, <code>Maiusc+Invio</code> va a capo.</p><h2 id="link-e-backlink" tabindex="-1">Link e backlink <a class="header-anchor" href="#link-e-backlink" aria-label="Permalink to &quot;Link e backlink&quot;">​</a></h2><ul><li><strong>Wikilink:</strong> <code>[[Nota]]</code>, con alias <code>[[Nota|testo]]</code>, titoli <code>[[Nota#Titolo]]</code> e blocchi <code>[[Nota#^id]]</code>. Scrivendo <code>[[</code> compare il completamento.</li><li><strong>Embed:</strong> <code>![[Nota]]</code>, <code>![[immagine.png|300]]</code>, <code>![[documento.pdf#page=2]]</code> incorporano contenuto.</li><li><strong>Link Markdown</strong> normali sono supportati; il formato dei nuovi link (wikilink o Markdown, percorso più breve/relativo) si sceglie in <em>Impostazioni → File e link</em>.</li><li><strong>Backlink:</strong> il pannello destro mostra chi punta alla nota corrente, anche come menzioni non collegate.</li><li>Passando il mouse su un link compare l&#39;<strong>anteprima</strong> della pagina, di un titolo o di un blocco.</li><li>Rinominare o spostare una nota aggiorna i link.</li></ul><h2 id="tag-e-proprieta" tabindex="-1">Tag e proprietà <a class="header-anchor" href="#tag-e-proprieta" aria-label="Permalink to &quot;Tag e proprietà&quot;">​</a></h2><ul><li><strong>Tag:</strong> <code>#idea</code>, <code>#progetto/clarae</code> (gerarchici). La scheda <em>Tag</em> elenca i tag con i conteggi. In Live, <code>Mod+clic</code> su un tag apre la ricerca di quel tag; in Sorgente il tag resta testo e il clic non fa nulla.</li><li><strong>Proprietà (frontmatter YAML):</strong> in cima alla nota, tra <code>---</code>. In Live il frontmatter è nascosto: il pannello <em>Proprietà</em> permette di aggiungere e modificare le proprietà con il tipo corretto (testo, numero, data, elenco, casella). In Sorgente lo scrivete come testo. Le proprietà <code>tags</code> e <code>aliases</code> hanno un significato speciale: gli alias diventano nomi alternativi per i link.</li></ul><h2 id="blocchi-di-ricerca-incorporati" tabindex="-1">Blocchi di ricerca incorporati <a class="header-anchor" href="#blocchi-di-ricerca-incorporati" aria-label="Permalink to &quot;Blocchi di ricerca incorporati&quot;">​</a></h2><p>Un blocco di codice di tipo <code>query</code> mostra il risultato di una ricerca direttamente nella nota (si aggiorna da solo). Vedi <a href="./ricerca.html">Ricerca</a>.</p><h2 id="segnalibri-e-workspace" tabindex="-1">Segnalibri e workspace <a class="header-anchor" href="#segnalibri-e-workspace" aria-label="Permalink to &quot;Segnalibri e workspace&quot;">​</a></h2><p><em>Aggiungi la nota ai segnalibri</em> (anche titoli, blocchi, ricerche, grafi) dalla palette; i segnalibri si sincronizzano. I <strong>workspace</strong> salvano e ripristinano la disposizione di pannelli e schede (restano sul dispositivo).</p>',14)])])}const g=o(t,[["render",n]]);export{u as __pageData,g as default};
